and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'scenePoint' and fcb.business_id = p.point_id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
and p.status = #{bo.status}
